import {stats,labels,modeLabels} from './core.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>t?new Date(t).toLocaleString('pt-BR'):'—';
export function dashboardMarkup(c){
 const s=stats(c.items),attempts=c.items.reduce((n,i)=>n+i.attempts,0),finished=c.items.filter(i=>!['pending','processing','sending'].includes(i.status)).length;
 const pct=Math.round(100*(s.sent||0)/(s.total||1));
 const events=c.items.flatMap(i=>i.history.map(h=>({...h,name:i.name||i.groupName||i.target,target:i.target}))).sort((a,b)=>b.at-a.at);
 const start=c.items.reduce((t,i)=>i.startedAt?Math.min(t,i.startedAt):t,Date.now());
 const errors=c.items.filter(i=>['error','invalid','uncertain','approval'].includes(i.status));
 const reasons=new Map();errors.forEach(i=>{const key=i.detail||labels[i.status];reasons.set(key,(reasons.get(key)||0)+1);});
 const average=(c.min+c.max)/2,minutes=Math.ceil((s.pending||0)*average/60);
 const metrics=[['Enviados',s.sent||0],['Pendentes',s.pending||0],['Erros / inválidos',(s.error||0)+(s.invalid||0)],['Incertos / aprovação',(s.uncertain||0)+(s.approval||0)],['Tentativas',attempts],['Enviados / total',pct+'%']];
 const x=c.interactive||{};
 return `<section class="campaign-dashboard"><h3>Visão geral da campanha</h3><div class="metrics dashboard-metrics">${metrics.map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="dashboard-grid"><article class="chart"><h3>Configuração e andamento</h3><dl><dt>Criada em</dt><dd>${date(c.createdAt)}</dd><dt>Primeira tentativa</dt><dd>${attempts?date(start):'—'}</dd><dt>Formato</dt><dd>${esc(modeLabels[c.mode])}</dd><dt>Processados</dt><dd>${finished} / ${s.total}</dd><dt>Limite diário configurado</dt><dd>${c.daily} tentativas</dd><dt>Lote atual</dt><dd>${c.sessionAttempts||0} / ${c.batch}</dd><dt>Espera estimada restante</dt><dd>~${minutes} min</dd></dl><p class="hint">Estimativa só dos intervalos, sem duração de envio, limites, pausas ou atrasos. Enviado não significa entregue/lido.</p></article><article class="chart"><h3>Conteúdo configurado</h3>${x.title?`<strong>${esc(x.title)}</strong>`:''}<div class="message-preview">${esc(c.text||'Sem legenda')}</div>${c.invite&&c.mode==='invite'?`<p class="wrap">${esc(c.invite)}</p>`:''}${(x.buttons||[]).map(b=>`<div class="preview-option">${esc(b.text)}<small>${esc(b.url||b.phoneNumber||b.id)}</small></div>`).join('')}${(x.sections||[]).map(s=>`<strong>${esc(s.title)}</strong>${s.rows.map(r=>`<div class="preview-option">${esc(r.title)}<small>${esc(r.description||'')}</small></div>`).join('')}`).join('')}${x.footer?`<p class="hint">${esc(x.footer)}</p>`:''}</article></div><div class="dashboard-grid"><article class="chart"><h3>Motivos que exigem atenção</h3>${[...reasons].sort((a,b)=>b[1]-a[1]).slice(0,8).map(([reason,n])=>`<div class="reason-row"><span>${esc(reason)}</span><strong>${n}</strong></div>`).join('')||'<p class="muted">Nenhuma ocorrência registrada.</p>'}</article><article class="chart"><h3>Atividade recente</h3><div class="activity">${events.slice(0,30).map(e=>`<div><span class="badge">${esc(labels[e.event]||({attempt:'Tentativa',manual:'Revisão manual'}[e.event])||e.event)}</span> <strong>${esc(e.name)}</strong><small>${date(e.at)}</small>${e.detail?`<small>${esc(e.detail)}</small>`:''}</div>`).join('')||'<p class="muted">Ainda não há atividade.</p>'}</div></article></div></section>`;
}
